package com.ripplenexus.salespilot.target.presentation;

import com.ripplenexus.salespilot.auth.domain.User;
import com.ripplenexus.salespilot.core.dto.ApiResponse;
import com.ripplenexus.salespilot.employee.domain.Employee;
import com.ripplenexus.salespilot.employee.infrastructure.EmployeeRepository;
import com.ripplenexus.salespilot.target.application.TargetService;
import com.ripplenexus.salespilot.target.domain.Target;
import com.ripplenexus.salespilot.target.presentation.dto.CreateTargetRequest;
import io.swagger.v3.oas.annotations.Operation;
import io.swagger.v3.oas.annotations.tags.Tag;
import jakarta.validation.Valid;
import org.springframework.http.ResponseEntity;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.web.bind.annotation.*;
import java.util.List;
import java.util.UUID;

@RestController
@RequestMapping("/targets")
@Tag(name = "Targets", description = "Sales targets and quota management endpoints")
public class TargetController {
    private final TargetService targetService;
    private final EmployeeRepository employeeRepository;

    @Operation(summary = "Get current user\'s active targets")
    @GetMapping("/me")
    @PreAuthorize("isAuthenticated()")
    public ResponseEntity<ApiResponse<List<Target>>> getMyTargets(@AuthenticationPrincipal User user) {
        Employee employee = employeeRepository.findByUserId(user.getId()).orElseThrow(() -> new com.ripplenexus.salespilot.core.exception.ResourceNotFoundException("Employee profile not found"));
        return ResponseEntity.ok(ApiResponse.success(targetService.getByEmployee(employee.getId())));
    }

    @Operation(summary = "Get targets for a specific employee")
    @GetMapping("/employee/{employeeId}")
    @PreAuthorize("hasAnyRole(\'ADMIN\', \'SALES_MANAGER\', \'SALES_EXEC\')")
    public ResponseEntity<ApiResponse<List<Target>>> getEmployeeTargets(@PathVariable UUID employeeId, @AuthenticationPrincipal User user) {
        boolean isAdminOrManager = user.getRoles().stream().anyMatch(r -> r.getName().equals("ADMIN") || r.getName().equals("SALES_MANAGER"));
        if (!isAdminOrManager) {
            Employee employee = employeeRepository.findByUserId(user.getId()).orElseThrow(() -> new com.ripplenexus.salespilot.core.exception.ResourceNotFoundException("Employee profile not found"));
            if (!employee.getId().equals(employeeId)) {
                throw new AccessDeniedException("You can only view your own sales targets.");
            }
        }
        return ResponseEntity.ok(ApiResponse.success(targetService.getByEmployee(employeeId)));
    }

    @Operation(summary = "Get all targets (Admin/Manager only)")
    @GetMapping
    @PreAuthorize("hasAnyRole(\'ADMIN\', \'SALES_MANAGER\')")
    public ResponseEntity<ApiResponse<List<Target>>> getAllTargets() {
        return ResponseEntity.ok(ApiResponse.success(targetService.getAllTargets()));
    }

    @Operation(summary = "Create target for employee (Admin/Manager only)")
    @PostMapping
    @PreAuthorize("hasAnyRole(\'ADMIN\', \'SALES_MANAGER\')")
    public ResponseEntity<ApiResponse<Target>> createTarget(@Valid @RequestBody CreateTargetRequest request) {
        Target created = targetService.createTarget(request.getEmployeeId(), request.getPeriod(), request.getType(), request.getTargetValue(), request.getPeriodStart(), request.getPeriodEnd());
        return ResponseEntity.ok(ApiResponse.success("Target created successfully", created));
    }

    @java.lang.SuppressWarnings("all")
    
    public TargetController(final TargetService targetService, final EmployeeRepository employeeRepository) {
        this.targetService = targetService;
        this.employeeRepository = employeeRepository;
    }
}
